-- Creates the payment_intents table.
--
-- A payment intent is a merchant's intention to collect an amount. Creating it
-- has no external effect; attempts against processors arrive with a later
-- table that references (merchant_id, id). Timestamps have no database default:
-- the application supplies them from its injected clock. Identifiers are UUIDs
-- generated by the application.

CREATE TABLE payment_intents (
  id uuid NOT NULL,
  merchant_id uuid NOT NULL,
  -- Minor units of the currency, for example 1000 for 10.00 USD.
  amount_minor bigint NOT NULL,
  currency varchar(3) NOT NULL,
  -- text with a CHECK instead of varchar(128): varchar silently cuts trailing
  -- spaces beyond its bound, which would store a reference other than the one
  -- the merchant sent.
  merchant_reference text NOT NULL,
  status varchar(20) NOT NULL,
  created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL,
  CONSTRAINT payment_intents_pkey PRIMARY KEY (id),
  CONSTRAINT payment_intents_merchant_id_fkey FOREIGN KEY (merchant_id) REFERENCES merchants (id),
  -- Target of the composite foreign keys of tables that belong to an intent, so
  -- that a row of one merchant can never reference another merchant's intent.
  CONSTRAINT payment_intents_merchant_id_id_key UNIQUE (merchant_id, id),
  -- One intent per merchant order, whatever idempotency key created it.
  CONSTRAINT payment_intents_merchant_reference_key UNIQUE (merchant_id, merchant_reference),
  CONSTRAINT payment_intents_amount_minor_check CHECK (amount_minor > 0),
  -- Only the format of the code is checked (as merchants.default_currency): the
  -- supported currencies are a rule of the application (Money).
  CONSTRAINT payment_intents_currency_check CHECK (currency ~ '^[A-Z]{3}$'),
  -- 1 to 128 visible ASCII characters: no spaces, control characters, or
  -- characters outside ASCII, so two references that look the same are the same.
  CONSTRAINT payment_intents_merchant_reference_check CHECK (merchant_reference ~ '^[!-~]{1,128}$'),
  -- The status values mirror PAYMENT_INTENT_STATUSES in packages/domain.
  CONSTRAINT payment_intents_status_check CHECK (
    status IN ('CREATED', 'PROCESSING', 'SUCCEEDED', 'FAILED', 'UNKNOWN')
  )
);

COMMENT ON TABLE payment_intents IS 'Payment intents of merchants. An intent is never deleted, so its merchant_reference stays taken for good.';
COMMENT ON COLUMN payment_intents.amount_minor IS 'Amount in minor units of currency, greater than zero. Read and written as bigint, never through a floating point number.';
COMMENT ON COLUMN payment_intents.merchant_reference IS 'The merchant''s own order identifier, case-sensitive and unique per merchant.';

-- What an intent is (its merchant, amount, currency, reference, identity, and
-- creation time) never changes; only its status and updated_at move.
CREATE FUNCTION payment_intents_reject_invalid_update() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF (NEW.id, NEW.merchant_id, NEW.amount_minor, NEW.currency,
      NEW.merchant_reference, NEW.created_at)
     IS DISTINCT FROM
     (OLD.id, OLD.merchant_id, OLD.amount_minor, OLD.currency,
      OLD.merchant_reference, OLD.created_at) THEN
    RAISE EXCEPTION 'payment_intents: only status and updated_at can be changed'
      USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER payment_intents_restrict_update
BEFORE UPDATE ON payment_intents
FOR EACH ROW
EXECUTE FUNCTION payment_intents_reject_invalid_update();

-- Deleting an intent would free its merchant_reference for a second order, so
-- deletion is rejected for every statement, including one that matches no row.
CREATE FUNCTION payment_intents_reject_delete() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'payment_intents: % is not allowed', TG_OP
    USING ERRCODE = 'restrict_violation';
END;
$$;

CREATE TRIGGER payment_intents_restrict_delete
BEFORE DELETE OR TRUNCATE ON payment_intents
FOR EACH STATEMENT
EXECUTE FUNCTION payment_intents_reject_delete();
